import React, { useState } from "react";
import { 
  Zap, Flame, BookOpen, Award, Download, Share2, 
  Target, CheckCircle, TrendingUp 
} from "lucide-react";
import "../App.css";

export default function Dashboard({ user }) {
  const [activeTab, setActiveTab] = useState("overview");

  // Mock data matching your screenshots
  const subjectStats = [
    { name: "Mathematics", quizzes: 6, accuracy: 74, xp: 282, color: "#10b981" },
    { name: "Physical Education", quizzes: 1, accuracy: 100, xp: 50, color: "#10b981" },
    { name: "Social Studies", quizzes: 1, accuracy: 67, xp: 33, color: "#f97316" },
    { name: "Science", quizzes: 1, accuracy: 50, xp: 37, color: "#f97316" }
  ];

  return (
    <div className="dashboard-container">
      {/* 1. Header Row */}
      <div className="dashboard-header-row">
        <div>
           <h1>My Dashboard</h1>
           <p style={{color: '#64748b', margin: '5px 0'}}>
             Welcome, {user?.name || 'Student'}! • Grade {user?.grade || '10'}
           </p>
        </div>
        <div style={{display: 'flex', gap: '10px'}}>
           <button className="btn-secondary" style={{fontSize: '0.9rem'}}><Download size={16}/> Report</button>
           <button className="btn-secondary" style={{fontSize: '0.9rem'}}><Share2 size={16}/> Share</button>
        </div>
      </div>

      {/* 2. Level Banner */}
      <div className="level-banner-large">
        <div className="level-badge-large">1</div>
        <div className="level-progress-info">
          <h3 style={{margin: 0, fontSize: '1.5rem'}}>Level 1</h3>
          <p style={{margin: '5px 0', opacity: 0.9}}>402 / 500 XP to next level</p>
          <div className="progress-bg">
            <div className="progress-fill" style={{width: '80%'}}></div>
          </div>
          <span style={{fontSize: '0.85rem', opacity: 0.8}}>98 XP until Level 2</span>
        </div>
        <div className="banner-stats-right">
          <div className="stat-unit"><strong>402</strong>Total XP</div>
          <div className="stat-unit"><strong>0</strong>Day Streak</div>
          <div className="stat-unit"><strong>2</strong>Certificates</div>
        </div>
      </div>

      {/* 3. Navigation Tabs */}
      <div className="dash-tabs">
        {["overview", "subjects", "certificates", "report"].map((tab) => (
          <button 
            key={tab} 
            className={`tab-btn ${activeTab === tab ? "active" : ""}`}
            onClick={() => setActiveTab(tab)}
          >
            {tab.charAt(0).toUpperCase() + tab.slice(1)}
          </button>
        ))}
      </div>

      {/* 4. Tab Content: OVERVIEW */}
      {activeTab === "overview" && (
        <>
          <div className="stats-grid">
            <OverviewStat icon={<Target/>} color="#dcfce7" textColor="#16a34a" label="Quizzes" val="9" />
            <OverviewStat icon={<TrendingUp/>} color="#dbeafe" textColor="#2563eb" label="Avg Score" val="74%" />
            <OverviewStat icon={<CheckCircle/>} color="#f3e8ff" textColor="#9333ea" label="Correct" val="29" />
            <OverviewStat icon={<Award/>} color="#ffedd5" textColor="#ea580c" label="Perfect" val="4" />
          </div>

          <div className="activity-card">
             <h3 style={{margin: '0 0 1rem'}}><TrendingUp size={20} style={{verticalAlign: 'middle', marginRight: '8px'}}/> Learning Activity (14 Days)</h3>
             <div className="chart-area">
                {/* Horizontal grid lines based on Screenshot 130234 */}
                <div style={{position: 'absolute', width: '100%', bottom: '25%', borderTop: '1px dashed #e2e8f0'}}></div>
                <div style={{position: 'absolute', width: '100%', bottom: '50%', borderTop: '1px dashed #e2e8f0'}}></div>
                <div style={{position: 'absolute', width: '100%', bottom: '75%', borderTop: '1px dashed #e2e8f0'}}></div>
                
                {/* Learning curve path */}
                <svg width="100%" height="100%" style={{position: 'absolute'}}>
                   <path d="M0,240 Q150,230 300,240 T600,240" fill="none" stroke="#10b981" strokeWidth="3" />
                </svg>
             </div>
             <div style={{display: 'flex', justifyContent: 'space-between', fontSize: '0.75rem', color: '#94a3b8', padding: '0 10px'}}>
                <span>30 Fri</span><span>31 Sat</span><span>1 Sun</span><span>2 Mon</span><span>3 Tue</span><span>4 Wed</span><span>5 Thu</span><span>6 Fri</span><span>7 Sat</span>
             </div>
          </div>
        </>
      )}

      {/* 5. Tab Content: SUBJECTS */}
      {activeTab === "subjects" && (
        <div className="subject-progress-grid">
          {subjectStats.map((sub, idx) => (
            <div key={idx} className="sub-progress-card">
              <div className="sub-card-header">
                <div>
                   <h4 style={{margin: 0, fontSize: '1.2rem'}}>{sub.name}</h4>
                   <span style={{fontSize: '0.85rem', color: '#64748b'}}>{sub.quizzes} quizzes</span>
                </div>
                <div className="accuracy-tag">{sub.accuracy}%</div>
              </div>
              <div style={{display: 'flex', justifyContent: 'space-between', fontSize: '0.85rem', marginBottom: '8px'}}>
                 <span>Accuracy</span><span>{sub.accuracy}%</span>
              </div>
              <div className="progress-bg" style={{height: '8px'}}>
                 <div className="progress-fill" style={{width: `${sub.accuracy}%`, background: sub.color}}></div>
              </div>
              <div style={{textAlign: 'right', fontSize: '0.85rem', marginTop: '8px', color: sub.color, fontWeight: '700'}}>
                 {sub.xp} XP Earned
              </div>
            </div>
          ))}
        </div>
      )}

      {/* 6. Tab Content: REPORT (Bar Chart) */}
      {activeTab === "report" && ( activeTab === "report" && (
        <div className="activity-card">
          <h3>XP by Subject</h3>
          <div style={{height: '300px', display: 'flex', alignItems: 'flex-end', gap: '2rem', padding: '20px', borderBottom: '1px solid #e2e8f0'}}>
             <div style={{flex: 1, background: '#10b981', height: '90%', borderRadius: '4px 4px 0 0'}}></div>
             <div style={{flex: 1, background: '#10b981', height: '20%', borderRadius: '4px 4px 0 0'}}></div>
             <div style={{flex: 1, background: '#10b981', height: '15%', borderRadius: '4px 4px 0 0'}}></div>
             <div style={{flex: 1, background: '#10b981', height: '18%', borderRadius: '4px 4px 0 0'}}></div>
          </div>
          <div style={{display: 'flex', justifyContent: 'space-between', fontSize: '0.85rem', color: '#64748b', padding: '10px 20px'}}>
             <span style={{flex: 1, textAlign: 'center'}}>Mathematics</span>
             <span style={{flex: 1, textAlign: 'center'}}>Physical Education</span>
             <span style={{flex: 1, textAlign: 'center'}}>Social Studies</span>
             <span style={{flex: 1, textAlign: 'center'}}>Science</span>
          </div>
        </div>
      ))}
    </div>
  );
}

// Helper Sub-component for individual stats
function OverviewStat({ icon, color, textColor, label, val }) {
  return (
    <div className="stat-box">
      <div className="stat-icon-circle" style={{ background: color, color: textColor }}>
        {icon}
      </div>
      <div>
        <h2 style={{ margin: 0, fontSize: '1.6rem' }}>{val}</h2>
        <span style={{ color: '#64748b', fontSize: '0.85rem', fontWeight: '500' }}>{label}</span>
      </div>
    </div>
  );
}
